  /// Returns the raw SVG XML string for the specified instrument icon.
  static String getSvgString(InstrumentIcon icon) {
    switch (icon) {
      case InstrumentIcon.guitar:
        return _guitarSvg;
      case InstrumentIcon.ukulele:
        return _ukuleleSvg;
      case InstrumentIcon.eguitar:
        return _eguitarSvg;
      case InstrumentIcon.bass:
        return _bassSvg;
      case InstrumentIcon.violin:
        return _violinSvg;
      case InstrumentIcon.cello:
        return _celloSvg;
      case InstrumentIcon.doubleBass:
        return _doubleBassSvg;
      case InstrumentIcon.piano:
        return _pianoSvg;
      case InstrumentIcon.trumpet:
        return _trumpetSvg;
      case InstrumentIcon.saxophone:
        return _saxophoneSvg;
      case InstrumentIcon.flute:
        return _fluteSvg;
      case InstrumentIcon.harp:
        return _harpSvg;
      case InstrumentIcon.tar:
        return _tarSvg;
      case InstrumentIcon.setar:
        return _setarSvg;
      case InstrumentIcon.kamancheh:
        return _kamanchehSvg;
    }
  }
}

/// Renders the vector icon for a musical instrument with M3 semantic styling.
class InstrumentIconWidget extends StatelessWidget {
  const InstrumentIconWidget({
    super.key,
    required this.icon,
    this.size = 36.0,
    this.color,
  });

  /// The instrument icon to render.
  final InstrumentIcon icon;

  /// Width and height of the icon (default 36.0 dp matching Kotlin `InstrumentButton`).
  final double size;

  /// Tint color for the vector. If null, defaults to [IconTheme.of(context).color].
  final Color? color;

  @override
  Widget build(BuildContext context) {
    final effectiveColor =
        color ??
        IconTheme.of(context).color ??
        Theme.of(context).colorScheme.onSurface;

    return Semantics(
      label: icon.name,
      child: SvgPicture.string(
        InstrumentIcons.getSvgString(icon),
        width: size,
        height: size,
        colorFilter: ColorFilter.mode(effectiveColor, BlendMode.srcIn),
      ),
    );
  }
}
